options.script:
let x = data.series[0].fields[1].values;
let y = data.series[0].fields[0].values;
let formater = new Intl.NumberFormat("en-US", {
    signDisplay: "exceptZero",
    maximumSignificantDigits: 3,
    useGrouping: false
}).format;

function getText(variable, value, small = "") {
    switch(`${variable}_${small}`) {
    case 'Exchange_small':return (value <=0 ? '(more export)' : '(more import)');
    case 'Exchange_':return (value <=0 ? '(more export / less import)' : '(more import / less export)');
    case 'Demand': case 'Demand_small':return (value >0 ? '(less demand)' : '(more demand)');
    default: return '';
  }
}

function customDataFormat(variable, value) {
  let delta = ((variable==='Demand' ? -1:1)*value) > 0 ? '▲' : '▼';
  let correctVal = formater((variable==='Demand' ? -1:1) * value );
  let info = getText(variable, value);
  return `${variable} ${info} <br> ${delta} ${formater(correctVal)}`;
}

let trace = {
  x: x,
  y: y,
  customdata: y.map((v,i) => customDataFormat(x[i], v)),
  text: y.map((v,i) => `${formater((x[i]==='Demand' ? -1:1) * v )}<br> ${getText(x[i], v, "small")}`),
  hovertemplate: '%{customdata} TWh' +
                  '<br>%{initial:.3g} → %{final:.3g} TWh<br>' +
                  '<extra></extra>',
};


return { data: [trace] };

options.helpers:
const messages = {
  "Main": {
    'en': `This waterfall chart shows changes in electricity generation by type, exchanges and demand between one period and another.

Choose whether you want to compare on a monthly or annual basis (monthly comparison is generally more up-to-date).  
Select the comparison zone, which can be a country, a continent, a group of countries or the whole world.  
Select the start of the reference period, the comparison period and the common duration.  
You can choose to display the production graph by type or not clean / fossil.`,
    'fr': `Ce diagramme en cascade montre l'évolution de la production d'électricité par type, des échanges et de la demande entre une période donnée et une autre.

Choisissez la comparaison sur une base mentuelle ou annuelle (celle mensuelle est généralement plus à jour).  
Choisissez la zone de comparaison pouvant être un pays, un continent, un groupe de pays ou le monde entier.  
Sélectionnez le début de la période de référence ainsi que celle de comparaison ainsi que la durée commune.  
Il est possible de choisir entre afficher le graphique de production par type ou pas propre / fossile.`
  }
}

handlebars.registerHelper('translate',
  (message) => messages[message][navigator.language] ?? messages[message]['en']);

